/**
 * GlucoVision i18n — Developer Guideline (MUST READ)
 * ------------------------------------------------------------------
 * ALL user-visible text MUST go through the translation system.
 * Do NOT hardcode English strings in JSX. Every string that a user
 * can read (headings, paragraphs, buttons, labels, placeholders,
 * aria-labels, toasts, alt text) must be a key in DICTS and rendered
 * via the t() hook.
 *
 * ✅ Correct:
 *   const { t } = useLang();
 *   <h1>{t("dashboardHeading")}</h1>
 *   <input placeholder={t("patientsSearchPh2")} />
 *   <button>{t("commonSaveLabel")}</button>
 *
 * ❌ Wrong — hardcoded (will be caught by lint):
 *   <h1>Dashboard — Shirpur Rural</h1>
 *   <input placeholder="Search patient…" />
 *   <button>Save</button>
 *
 * How to add new content:
 *  1. Add a new key to baseEn (the `en` dict) — use camelCase with
 *     a clear namespace, e.g. "pharmacyNewOrderBtn2".
 *  2. Add at least an English value and a Hindi value in the `hi` dict.
 *     Other languages (ta, te, kn, ml, bn, mr, gu, pa) automatically
 *     fall back to English via `t()` (DICTS[lang]?.[k] || DICTS.en[k]),
 *     so you only NEED to provide `en` + `hi`. Provide more when able.
 *  3. Use the key in JSX: `{t("yourNewKey")}`.
 *  4. Run `npm run lint:i18n` (or `npx tsc --noEmit`) to verify no
 *     hardcoded strings remain.
 *
 * Lint helper: `scripts/check-i18n.js` (and `npm run lint:i18n`) scans
 * src/app and src/components for JSX text / placeholder / alt that is
 * not wrapped in t(). CI should fail if any are found.
 * Never add user text without a DICTS entry — it breaks 10-language
 * support for Bharat.
 */
